// Helper function to safely construct the full path
// Returns true on success, false on error (e.g., path too long)
bool safe_construct_path(char* buffer, size_t buffer_size, const char* dest_path, const char* entry_pathname) {
    if (!dest_path || !entry_pathname) {
        return false;
    }

    size_t dest_len = strlen(dest_path);
    size_t entry_len = strlen(entry_pathname);

    // Check for potential overflow and ensure space for '/' and null terminator
    if (dest_len + 1 + entry_len + 1 > buffer_size) {
        return false; // Path too long
    }

    // Construct the path: dest_path/entry_pathname
    int written = snprintf(buffer, buffer_size, "%s/%s", dest_path, entry_pathname);
    if (written < 0 || written >= buffer_size) {
        return false; // Error during snprintf or buffer too small
    }

    return true;
}

// Helper function to check for directory traversal attempts
// Returns true if the path is considered safe, false otherwise.
bool is_safe_path(const char* path) {
    if (!path) {
        return false;
    }
    // Basic check: disallow paths starting with ".." or containing "/../"
    if (strncmp(path, "..", 2) == 0 || strstr(path, "/../") != NULL) {
        return false;
    }
    return true;
}

